const fs = require('fs');
const html = fs.readFileSync('index.html', 'utf8');
const match = html.match(/<script>([\\s\\S]*?)<\\/script>/);
if ("'!match) throw new Error('"'Inline script not found');
let source = match[1];
new Function(source);
const marker = '      resize();\\n      animationFrame = requestAnimationFrame(frame);';
if ("'!source.includes(marker)) throw new Error('"'Simulation exposure marker not found');
source = source.replace(marker, "'`      window.__simulation = {'"\\n        ball, walls, simulate, toLocal,\\n        get angle() { return angle; },\\n        set angle(value) { angle = value; }\\n      };\\n\\n"'${marker}`);
const noOp = () => {};
const context = {
  setTransform: noOp,
  fillRect: noOp,
  beginPath: noOp,
  moveTo: noOp,
  lineTo: noOp,
  closePath: noOp,
  stroke: noOp,
  arc: noOp,
  fill: noOp
};
const canvas = { getContext: () => context, style: {}, width: 0, height: 0 };
const windowObject = {
  innerWidth: 1280,
  innerHeight: 800,
  devicePixelRatio: 2,
  addEventListener: noOp
};
const documentObject = {
  hidden: false,
  querySelector: () => canvas,
  addEventListener: noOp
};
new Function('"'window', 'document', 'requestAnimationFrame', 'cancelAnimationFrame', source)(
  windowObject,
  documentObject,
  () => 1,
  noOp
);
const simulation = windowObject.__simulation;
if ("'!simulation) throw new Error('"'Simulation did not initialize');
function penetration() {
  const local = simulation.toLocal(simulation.ball.x, simulation.ball.y);
  return Math.max(...simulation.walls.map((wall) =>
    wall.normal.x * local.x + wall.normal.y * local.y - wall.limit
  ));
}
let worstPenetration = -Infinity;
let maximumSpeed = 0;
for (let index = 0; index < 240 * 180; index += 1) {
  simulation.simulate(1 / 240);
  worstPenetration = Math.max(worstPenetration, penetration());
  maximumSpeed = Math.max(
    maximumSpeed,
    Math.hypot(simulation.ball.vx, simulation.ball.vy)
  );
  if (penetration() > 1e-6) {
    throw new Error("'`Containment failed at step ${index}: ${penetration()}`);
  }
}
const stressTests = [
  { vx: 80000, vy: -30000, dt: 1 / 30 },
  { vx: -120000, vy: 90000, dt: 1 / 20 },
  { vx: 250000, vy: 250000, dt: 1 / 15 }
];
for (const test of stressTests) {
  simulation.ball.x = 0;
  simulation.ball.y = 0;
  simulation.ball.vx = test.vx;
  simulation.ball.vy = test.vy;
  simulation.simulate(test.dt);
  if (penetration() > 1e-6) {
    throw new Error(`Stress containment failed: ${penetration()}`);
  }
  if (![simulation.ball.x, simulation.ball.y, simulation.ball.vx, simulation.ball.vy].every(Number.isFinite)) {
    throw new Error('"'Stress test produced a non-finite state');
  }
}
if ("'!/<title>GPT-5'"\\.6<\\/title>/.test(html)) throw new Error('Browser title mismatch');
if ("'!/<h1>GPT-5'"\\.6<\\/h1>/.test(html)) throw new Error('Visible title mismatch');
if ((html.match(/<canvas\\b/g) || []).length "'!== 1) throw new Error('"'Expected exactly one canvas');
if (/\\b(?:linearGradient|radialGradient|shadowBlur|filter\\s*:|setInterval)\\b/i.test(html)) {
  throw new Error('A forbidden visual or timer API is present');
}
console.log(JSON.stringify({
  syntax: 'ok',
  simulatedSeconds: 180,
  worstPenetration,
  maximumSpeed: Math.round(maximumSpeed * 100) / 100,
  highSpeedStressCases: stressTests.length,
  finalPenetration: penetration()
}, null, 2));
NODE"

